16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Derives an owner's numeric membership level from the owner's own fields.
20	 *
21	 * <p>The level starts at {@value #MIN}; a present email adds one; having no
22	 * namesakes (namesakeCount is 0) adds one; and tenure of more than
23	 * {@value #TENURE_DAYS} days adds one; the total is capped at {@value #MAX}.
24	 * Level 4 requires tenure, so a newly registered owner (zero tenure) never
25	 * exceeds level 3 no matter how the other factors fall.
26	 */
27	public final class MembershipLevel {
28	
29	    /** The level every owner starts at. */
30	    public static final int MIN = 1;
31	
32	    /** The highest level attainable; only reached once the tenure factor applies. */
33	    public static final int MAX = 4;
34	
35	    /** Tenure, in days, that an owner must exceed to earn the level-4 tenure factor. */
36	    public static final int TENURE_DAYS = 365;
37	
38	    private MembershipLevel() {
39	    }
40	
41	    /**
42	     * Derive the membership level for the given owner.
43	     *
44	     * @param owner the owner (must not be {@code null}).
45	     * @return the level, from {@value #MIN} to {@value #MAX}.
46	     */
47	    public static int of(Owner owner) {
48	        int level = MIN;
49	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
50	            level++;
51	        }
52	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
53	            level++;
54	        }
55	        if (Tenure.inDays(owner) > TENURE_DAYS) {
56	            level++;
57	        }
58	        return Math.min(level, MAX);
59	    }
60	}
