16	package org.springframework.samples.petclinic.model;
17	
18	import java.time.LocalDate;
19	import java.time.temporal.ChronoUnit;
20	
21	/**
22	 * How long an owner has been a member, in whole days, measured from their
23	 * {@link Owner#getRegistrationDate() registrationDate} to the current date. A freshly
24	 * registered owner has zero tenure, and an owner without a registration date has none.
25	 */
26	public final class Tenure {
27	
28	    private Tenure() {
29	    }
30	
31	    /**
32	     * Derive the owner's tenure in whole days as of today.
33	     *
34	     * @param owner the owner (must not be {@code null}).
35	     * @return the number of days since registration, or {@code 0} when the owner has no
36	     *         registration date (or has not yet reached it).
37	     */
38	    public static long inDays(Owner owner) {
39	        LocalDate registrationDate = owner.getRegistrationDate();
40	        if (registrationDate == null) {
41	            return 0;
42	        }
43	        return Math.max(0, ChronoUnit.DAYS.between(registrationDate, LocalDate.now()));
44	    }
45	}
