3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many owners the new owner's household holds once this owner is added: the
9	 * existing owners that share this owner's deterministic {@code householdId} (same last name and
10	 * postcode, see {@link OwnerHouseholds}) plus the new owner itself. A household with no other
11	 * members has a size of 1.
12	 *
13	 * <p>Runs after {@link AssignOwnerHousehold} — which assigns the {@code householdId} this counts
14	 * on — and before {@link SaveOwner}, so the count reflects the household membership at creation
15	 * time and never counts the new owner twice.
16	 */
17	public class AssignOwnerHouseholdSize {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        int count = 1; // the new owner, not yet saved
21	        String householdId = owner.getHouseholdId();
22	        if (householdId != null) {
23	            for (Owner existing : ownerRepository.findAll()) {
24	                if (householdId.equals(existing.getHouseholdId())) {
25	                    count++;
26	                }
27	            }
28	        }
29	        owner.setHouseholdSize(count);
30	    }
31	}
