15	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
16	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
17	import org.springframework.samples.petclinic.util.Luhn;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
29	    @Mapping(target = "initials", expression = "java(initials(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(locality(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
36	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /** The owner's stored E.164 telephone formatted for humans - see {@link OwnerTelephones#toDisplay}. */
41	    default String telephoneDisplay(Owner owner) {
42	        if (owner == null) {
43	            return null;
44	        }
45	        return OwnerTelephones.toDisplay(owner.getTelephone());
46	    }
47	
48	    /** The owner's age band derived from birthDate against registrationDate - see {@link AgeBand};
49	     * null when either date is absent. */
50	    default String ageBand(Owner owner) {
51	        if (owner == null) {
52	            return null;
53	        }
54	        AgeBand ageBand = AgeBand.forOwner(owner);
55	        return ageBand == null ? null : ageBand.name();
56	    }
57	
58	    /** The owner's derived duplicate-detection key - see {@link OwnerIdentities}. */
59	    default String identityKey(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        return OwnerIdentities.of(owner);
64	    }
65	
66	    /** The owner's preferred contact channel - 'EMAIL' when an email is present, otherwise 'PHONE'. */
67	    default String contactPreference(Owner owner) {
68	        if (owner == null) {
69	            return null;
70	        }
71	        return ContactPreference.forOwner(owner).name();
72	    }
73	
74	    /** The canonical region derived from the owner's postcode - the same REGION that forms the
75	     * customer code (see {@link OwnerIdentities} and the {@code <REGION>-<HASH8>} customer code),
76	     * or 'UNKNOWN' when the postcode resolves to no known region. */
77	    default String locality(Owner owner) {
78	        if (owner == null) {
79	            return null;
80	        }
81	        return Locality.forPostcode(owner.getPostcode());
82	    }
83	
84	    /** Format the stored names as 'LastName, FirstName'. */
85	    default String displayName(Owner owner) {
86	        if (owner == null) {
87	            return null;
88	        }
89	        return owner.getLastName() + ", " + owner.getFirstName();
90	    }
91	
92	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
93	    default String initials(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        return initial(owner.getFirstName()) + initial(owner.getLastName());
98	    }
99	
100	    private static String initial(String name) {
101	        if (name == null || name.isEmpty()) {
102	            return "";
103	        }
104	        return Character.toUpperCase(name.charAt(0)) + ".";
105	    }
106	
107	    /**
108	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
109	     * last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Derived from the owner's
110	     * own fields; null until both the customer code and registration date are assigned.
111	     */
112	    default String membershipNumber(Owner owner) {
113	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
114	            return null;
115	        }
116	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
117	    }
118	
119	    /** The Luhn check digit over the digits of the owner's customerCode; null until a code is assigned. */
120	    default Integer checkDigit(Owner owner) {
121	        if (owner == null || owner.getCustomerCode() == null) {
122	            return null;
123	        }
124	        return Luhn.checkDigit(owner.getCustomerCode());
125	    }
126	
127	    /**
128	     * The owner's numeric membership level, derived from the owner's own fields; null when there
129	     * is no owner.
130	     *
131	     * @see MembershipLevel
132	     */
133	    default Integer membershipLevel(Owner owner) {
134	        if (owner == null) {
135	            return null;
136	        }
137	        return MembershipLevel.of(owner);
138	    }
139	
140	    Owner toOwner(OwnerDto ownerDto);
141	
142	    @Mapping(target = "id", ignore = true)
143	    @Mapping(target = "pets", ignore = true)
144	    Owner toOwner(OwnerFieldsDto ownerDto);
145	
146	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
147	
148	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
149	
150	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
151	        OwnerPageDto ownerPageDto = new OwnerPageDto();
152	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
153	        ownerPageDto.setPage(ownerPage.getNumber());
154	        ownerPageDto.setSize(ownerPage.getSize());
155	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
156	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
157	        return ownerPageDto;
158	    }
159	}
